// If node 3 found a matching row, it will have come through with a "Phone" value.
// If nobody matched (brand-new number), "Always Output Data" still gives us one
// empty item to work with here - so we check whether Phone is actually filled in.
const foundExistingRow = Boolean($json.Phone);
const isNew = !foundExistingRow;

// Bring back the original WhatsApp message data (from the very first node),
// no matter what node 3 returned.
const original = $('1. New WhatsApp Message (Trigger)').first().json;

return {
  json: {
    ...original,
    is_new: isNew
  }
};

